package app.notate.core.store.library

import app.notate.core.store.DocStoreFactory
import java.io.File

/** Outcome of [LibraryRebuilder.rebuild]; [failed] lists document directories that could not be read. */
data class RebuildResult(val restored: Int, val failed: List<String>)

/**
 * Rebuilds document rows of an empty library from `<docsDir>/<id>/doc.db` (03-data-model §7). Folder membership,
 * tags, pins and trash marks are lost; the search index is regenerated by OCR backfill.
 */
class LibraryRebuilder(private val docsDir: File, private val docStores: DocStoreFactory, private val library: LibraryStore) {
    suspend fun rebuild(): RebuildResult {
        var restored = 0
        val failed = ArrayList<String>()
        val dirs = docsDir.listFiles { f -> f.isDirectory && File(f, "doc.db").exists() }?.sortedBy { it.name } ?: emptyList()
        for (dir in dirs) {
            try {
                docStores.open(dir, readOnly = true).use { store ->
                    val meta = store.readMeta()
                    library.upsert(
                        DocumentEntry(
                            meta.id, meta.title, meta.kind, null, meta.createdAt, meta.modifiedAt, null,
                            store.readPages().size, 0L, false, null, emptySet(),
                        ),
                    )
                }
                restored++
            } catch (e: Exception) {
                failed += dir.name
            }
        }
        return RebuildResult(restored, failed)
    }
}
